mapper.select:
SELECT c.id, c.withdrawal_id, c.phase, c.outcome, c.master_enabled, c.failed_rules, c.config_version, c.decided_at
FROM wallet_withdrawal w JOIN wallet_withdraw_rule_check c ON c.id = w.last_check_id
WHERE w.id IN #{i}

SELECT COUNT(*) FROM wallet_withdrawal w
WHERE w.user_id = #{userId} AND w.created_at >= #{from} AND w.created_at < #{to} AND w.id <= #{upToId}
  AND NOT EXISTS (SELECT 1 FROM wallet_withdraw_event e WHERE e.withdrawal_id = w.id AND e.to_status = 'CANCELLED' AND e.actor LIKE 'user:%')
